gHJ(){return"\u0625\u0636\u0627\u0641\u0629 \u062d\u0633\u0627\u0628 \u0645\u0635\u0631\u0641\u064a"},
gHN(){return"\u0623\u0639\u0637\u0647 \u0627\u0633\u0645\u064b\u0627."},
gSz(){return"\u0644\u0645 \u064a\u062a\u0645 \u0627\u0644\u0639\u062b\u0648\u0631 \u0639\u0644\u0649 \u0641\u0631\u0639 \u2014 \u0642\u0645 \u0628\u0625\u0639\u062f\u0627\u062f \u0639\u0645\u0644\u0643 \u0623\u0648\u0644\u0627\u064b."},
gSo(){return"\u0627\u0644\u062d\u0633\u0627\u0628"},
gSs(){return"\u0627\u0644\u0628\u0646\u0643"},
